INSERT INTO user_numeric_v2(name,active,created_at) SELECT name,active,created_at FROM `user` ORDER BY created_at,id;
INSERT INTO pf_records_numeric_v2(kind,record_key,owner_id,version,name,saved_at,status,summary,payload)
INSERT INTO pf_resources_numeric_v2(hash,relative_path,bytes,released_at,created_at) SELECT id,relative_path,bytes,released_at,created_at FROM pf_resources ORDER BY created_at,id;
INSERT INTO pf_resource_refs_numeric_v2(record_id,resource_id) SELECT r.id,a.id FROM pf_resource_refs f JOIN pf_records_numeric_v2 r ON r.kind=f.kind AND r.record_key=f.record_id JOIN pf_resources_numeric_v2 a ON a.hash=f.resource_id ORDER BY r.id,a.id;
INSERT INTO pf_requests_numeric_v2(request_key,user_id,digest,response,created_at) SELECT q.id,n.id,q.digest,q.response,q.created_at FROM pf_requests q JOIN `user` u ON u.id=q.user_id JOIN user_numeric_v2 n ON n.name=u.name ORDER BY q.created_at,q.id;
INSERT INTO pf_transfers_numeric_v2(request_id,batch_id,batch_key,from_user,to_user,transferred_at) SELECT q.id,b.id,t.batch_id,n1.id,n2.id,t.transferred_at FROM pf_transfers t JOIN pf_requests_numeric_v2 q ON q.request_key=t.id LEFT JOIN pf_records_numeric_v2 b ON b.kind='batch' AND b.record_key=t.batch_id JOIN `user` u1 ON u1.id=t.from_user JOIN user_numeric_v2 n1 ON n1.name=u1.name JOIN `user` u2 ON u2.id=t.to_user JOIN user_numeric_v2 n2 ON n2.name=u2.name ORDER BY t.transferred_at,t.id;
INSERT INTO pf_migrations_numeric_v2(installation_key,kind,local_key,cloud_id,cloud_key) SELECT m.installation,m.kind,CASE WHEN m.kind='pools' AND n.id IS NOT NULL THEN CAST(n.id AS CHAR) ELSE m.local_id END,r.id,m.cloud_id FROM pf_migrations m LEFT JOIN pf_records_numeric_v2 r ON r.kind=m.kind AND r.record_key=m.cloud_id LEFT JOIN `user` u ON m.kind='pools' AND u.id=m.local_id LEFT JOIN user_numeric_v2 n ON n.name=u.name ORDER BY m.installation,m.kind,m.local_id;
