SELECT r.kind,r.id,n.id,r.version,r.name,r.saved_at,r.status,r.summary,r.payload FROM pf_records r LEFT JOIN `user` u ON u.id=r.owner_id LEFT JOIN user_numeric_v2 n ON n.name=u.name ORDER BY r.saved_at,r.kind,r.id;
UPDATE pf_records_numeric_v2 j JOIN pf_records old ON old.kind=j.kind AND old.id=j.record_key JOIN pf_records_numeric_v2 r ON r.kind='review' AND r.record_key=old.source_review_id SET j.source_review_id=r.id WHERE j.kind='job';
